//Asigna estado de alarma a variables globales de alarmas desde la 500 a las 629
var nombre = "";
for (var i = 0; i < 130; i++) {
    nombre = "PLC39_alarma" + i;
    //revisión si alarma está inhibida, dirección PLC comienza en 37
    if (msg.payload[37 + i])
        global.set(nombre, "inhibida");
    else

        //revisión si alarma está reconocida, dirección PLC comienza en 310
        if (!msg.payload[310 + i] && msg.payload[500 + i])
            global.set(nombre, "noReconocida");
        else

            //revisión si alarma está activa, dirección PLC comienza en 500
            if (msg.payload[500 + i] && msg.payload[310 + i])
                global.set(nombre, "activa_reconocida");
            else
                global.set(nombre, "inactiva_reconocida");

}




