    estado_alarma = global.get("PLC40_alarma" + i);
    if (estado_alarma == "inhibida")
        color = global.get("global_color_inhibida");

    else if (estado_alarma == "noReconocida") {
        if (msg.payload)
            color = global.get("global_color1_noReconocida");
